1. SELECT ROUND(AVG(sr.reading_value)) AS avg_voltage_kv FROM sensor_readings sr WHERE sr.sensor_type = 'voltage' AND sr.unit = 'kV';
2. SELECT ROUND(AVG(sr.reading_value), 0) AS avg_voltage_kv FROM sensor_readings sr JOIN assets a ON sr.asset_id = a.asset_id WHERE sr.sensor_type = 'voltage' AND sr.unit = 'kV';
3. SELECT CAST(ROUND(AVG(sr.reading_value)) AS INTEGER) AS avg_voltage_kv FROM sensor_readings sr JOIN assets a ON sr.asset_id = a.asset_id JOIN locations l ON a.location_id = l.location_id WHERE sr.sensor_type = 'voltage' AND sr.unit = 'kV';
